class IncidentNoteListView(LoginRequiredMixin, ListView):
    model = IncidentNote
    context_object_name = 'notes'
    template_name = 'incidents/notes_list.html'

    def get_queryset(self):
        incident_id = self.request.GET.get('incident_id')
        incident = get_object_or_404(Incident, id=incident_id, organization=self.request.user.organization)
        return IncidentNote.objects.filter(incident=incident).order_by('created_at')
